function solution(n) {
  // Generate first n Fibonacci numbers

}

solution:
function solution(n) {
  if (n === 0) return [];
  if (n === 1) return [0];
  const result = [0, 1];
  for (let i = 2; i < n; i++) {
    result.push(result[i-1] + result[i-2]);
  }
  return result;
}

starterCode:
function solution(max) {
  // Find all prime numbers up to max

}

solution:
function solution(max) {
  const primes = [];
  for (let num = 2; num <= max; num++) {
    let isPrime = true;
    for (let i = 2; i < num; i++) {
      if (num % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.push(num);
    }
  }
  return primes;
}
